using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
internal static class DayDashboardAcceptance {
 internal static WorkTask Task(string id,string title,string due,string priority="Normale"){return new WorkTask{id=id,title=title,project="Travail",due=due,priority=priority,status="todo",notes=""};}
 internal static void Test(string folder){
  var store=new Store(Path.Combine(folder,"day-dashboard"));var d=store.Value;string today=DateTime.Today.ToString("yyyy-MM-dd");d.tasks.Add(Task("late","En retard",DateTime.Today.AddDays(-2).ToString("yyyy-MM-dd")));d.tasks.Add(Task("today","Aujourd’hui",today));d.tasks.Add(Task("future","Plus tard",DateTime.Today.AddDays(5).ToString("yyyy-MM-dd"),"Haute"));d.tasks.Add(Task("four","Autre tâche",""));Store.Validate(d);
  if(String.Join(",",DayDashboard.Priorities(d,DateTime.Today).Select(t=>t.id))!="late,today,future")throw new Exception("La proposition doit privilégier le retard puis aujourd’hui.");
  DayDashboard.Choose(d,new[]{"today","four"},DateTime.Today);d.tasks.First(t=>t.id=="today").status="done";store.Save();store=new Store(store.Root);d=store.Value;if(!d.settings.Day.chosen||DayDashboard.Priorities(d,DateTime.Today).Count!=2||DayDashboard.Priorities(d,DateTime.Today)[0].status!="done")throw new Exception("Les priorités terminées doivent rester dans le plan du jour après redémarrage.");
  bool refused=false;try{DayDashboard.Choose(d,d.tasks.Select(t=>t.id),DateTime.Today);}catch(InvalidDataException){refused=true;}if(!refused)throw new Exception("Quatre priorités acceptées.");d.settings.Day.date=DateTime.Today.AddDays(-1).ToString("yyyy-MM-dd");Store.Validate(d);if(d.settings.Day.chosen||d.settings.Day.priorityIds.Count!=0)throw new Exception("Le plan de la veille n’a pas été renouvelé.");
  d.pages.Add(new NotePage{id="resume-note",title="Première version",body="Texte conservé",updated=DateTime.Now.ToString("o")});DayDashboard.Record(d,"note","resume-note",DateTime.Now);d.pages[0].title="Titre modifié";if(DayDashboard.Title(d,d.settings.Day.recent[0])!="Titre modifié")throw new Exception("Le titre récent est périmé.");DayDashboard.Record(d,"project","Travail",DateTime.Now);DayDashboard.Record(d,"note","resume-note",DateTime.Now);if(d.settings.Day.recent.Count!=2||d.settings.Day.recent[0].kind!="note")throw new Exception("Historique dupliqué ou mauvais ordre.");d.settings.PrivacyMode=true;DayDashboard.Record(d,"project","Personnel",DateTime.Now);d.settings.PrivacyMode=false;if(d.settings.Day.recent.Count!=2)throw new Exception("Navigation privée enregistrée.");d.pages[0].trashed=true;if(DayDashboard.Exists(d,d.settings.Day.recent[0]))throw new Exception("Note supprimée proposée en reprise.");if(DayDashboard.Exists(d,new ResumeEntry{kind="document",id=Path.Combine(folder,"missing.txt")}))throw new Exception("Fichier absent proposé en reprise.");
  var work=new LaunchMode{id="work-home",name="Travail",homePreset="Travail",homeProject="Travail"};var personal=new LaunchMode{id="personal-home",name="Perso",homePreset="Perso"};d.modes.Add(work);d.modes.Add(personal);Store.Validate(d);var before=DayDashboard.CloneLayout(d.settings.HomeBlocks);DayDashboard.Activate(d,work);d.settings.HomeBlocks.First(b=>b.id=="priorities").height=555;DayDashboard.Move(d,"resume","today",2);DayDashboard.RememberLayout(d);var clone=LaunchModes.Clone(work);clone.homeLayout[0].height=222;if(work.homeLayout[0].height==222)throw new Exception("La modification d’un brouillon change le mode enregistré.");DayDashboard.Activate(d,personal);if(!d.settings.HomeBlocks.First(b=>b.id=="finance").visible)throw new Exception("Accueil personnel non appliqué.");DayDashboard.Activate(d,work);if(d.settings.HomeBlocks.First(b=>b.id=="priorities").height!=555||d.settings.HomeBlocks.First(b=>b.id=="resume").column!=2)throw new Exception("Disposition du mode non conservée.");store.Save();var reloaded=new Store(store.Root);if(reloaded.Value.settings.Day.activeModeId!=work.id)throw new Exception("Mode actif perdu au redémarrage.");DayDashboard.ExitRoutine(d);if(String.Join(",",d.settings.HomeBlocks.Select(b=>b.id+":"+b.column+":"+b.height))!=String.Join(",",before.Select(b=>b.id+":"+b.column+":"+b.height)))throw new Exception("Retour à l’accueil d’origine incorrect.");DayDashboard.Activate(d,work);d.modes.Remove(work);Store.Validate(d);if(d.settings.Day.activeModeId!=""||d.settings.Day.homeBeforeRoutine!=null)throw new Exception("Suppression d’un mode actif mal gérée.");
  d.settings.Day=null;Store.Validate(d);if(d.settings.Day==null||d.tasks.Count!=4||d.pages[0].body!="Texte conservé")throw new Exception("Migration des réglages destructrice.");File.WriteAllText(Path.Combine(folder,"DAY_MODEL_PASS.txt"),"PASS: ordering, manual priorities, completion and restart, three-item limit, next-day reset, renamed/deleted notes, missing files, privacy, recent-item deduplication, per-mode layouts, deep clone, restart, restore and deleted active mode, legacy migration.");
 }
}
